import React, { useMemo } from 'react';
import { motion } from 'framer-motion';

/**
 * A futuristic, glassmorphic stats card component with neural network animations
 */
const StatsCard = ({ title, value, description, icon, color = 'blue', theme }) => {
  // Color mapping for different card types
  const colors = {
    blue: {
      bgFrom: 'from-blue-500/10',
      bgTo: 'to-blue-700/5',
      border: 'border-blue-500/20',
      glow: 'rgba(59, 130, 246, 0.35)',
      icon: 'text-blue-400',
      particles: 'bg-blue-300'
    },
    green: {
      bgFrom: 'from-emerald-500/10',
      bgTo: 'to-emerald-700/5',
      border: 'border-emerald-500/20',
      glow: 'rgba(16, 185, 129, 0.35)',
      icon: 'text-emerald-400',
      particles: 'bg-emerald-300'
    },
    purple: {
      bgFrom: 'from-violet-500/10',
      bgTo: 'to-violet-700/5',
      border: 'border-violet-500/20',
      glow: 'rgba(139, 92, 246, 0.35)',
      icon: 'text-violet-400',
      particles: 'bg-violet-300'
    },
    cyan: {
      bgFrom: 'from-cyan-500/10',
      bgTo: 'to-cyan-700/5',
      border: 'border-cyan-500/20',
      glow: 'rgba(6, 182, 212, 0.35)',
      icon: 'text-cyan-400',
      particles: 'bg-cyan-300'
    },
    neural: {
      bgFrom: 'from-neural-400/10',
      bgTo: 'to-neural-600/5',
      border: 'border-neural-400/20',
      glow: 'rgba(100, 200, 255, 0.35)',
      icon: 'text-neural-400',
      particles: 'bg-neural-300'
    }
  };

  // Reduce the number of particles and memoize them for better performance
  const particlePositions = useMemo(() => {
    return Array.from({ length: 3 }).map(() => ({
      x: Math.random() * 100,
      y: Math.random() * 100,
      size: Math.random() * 3 + 1,
    }));
  }, []);

  // Simplified card variants for animations
  const cardVariants = {
    hover: { 
      y: -3,
      boxShadow: `0 10px 20px -8px ${colors[color].glow}`,
      transition: { duration: 0.2, ease: "easeOut" }
    },
    tap: { 
      scale: 0.98,
      transition: { duration: 0.1, ease: "easeOut" }
    }
  };

  return (
    <motion.div
      className={`relative overflow-hidden rounded-xl bg-gradient-to-br ${colors[color].bgFrom} ${colors[color].bgTo} backdrop-blur-xl
        border ${colors[color].border} p-5 h-full`}
      initial={{ boxShadow: `0 5px 15px -5px transparent` }}
      whileHover="hover"
      whileTap="tap"
      variants={cardVariants}
      style={{ 
        backdropFilter: 'blur(10px)',
      }}
    >
      {/* Simplified glassmorphic effects */}
      <div className="absolute inset-0 overflow-hidden">
        {/* Static background grid */}
        <div className="absolute inset-0 opacity-10" 
          style={{ 
            backgroundImage: `linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px), 
                              linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px)`,
            backgroundSize: '20px 20px'
          }} 
        />
        
        {/* Top glowing border */}
        <div className="absolute top-0 left-5 right-5 h-px bg-gradient-to-r from-transparent via-white/30 to-transparent" />
        
        {/* Reduced number of particles with simplified animations */}
        {particlePositions.map((particle, i) => (
          <div
            key={`particle-${i}`}
            className={`absolute rounded-full ${colors[color].particles}`}
            style={{
              left: `${particle.x}%`,
              top: `${particle.y}%`,
              width: `${particle.size}px`,
              height: `${particle.size}px`,
              opacity: 0.2,
            }}
          />
        ))}
      </div>
      
      {/* Card Content */}
      <div className="relative z-10">
        <div className="flex justify-between items-start mb-3">
          <h3 className={`text-sm font-medium text-gray-200 opacity-90`}>
            {title}
          </h3>
          
          {/* Icon with simplified effect */}
          <div className={`${colors[color].icon} p-1.5 rounded-lg bg-white/5`}>
            {icon}
          </div>
        </div>
        
        {/* Card value with static styling instead of animation */}
        <div className="mb-2">
          <div 
            className="text-2xl font-bold text-white"
            style={{ 
              textShadow: `0 0 8px ${colors[color].glow}` 
            }}
          >
            {value}
          </div>
        </div>
        
        {/* Description without animation */}
        <p className="text-xs text-gray-300/80 leading-relaxed">
          {description}
        </p>
        
        {/* Simplified interaction indicator */}
        <div 
          className="absolute bottom-2 right-2 w-2 h-2 rounded-full bg-white/30"
        />
      </div>
    </motion.div>
  );
};

export default React.memo(StatsCard); 