import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../../contexts/ThemeContext';
import { useNotification } from '../../components/NotificationContext';

// Premium Dashboard Components
import GreetingHeader from './GreetingHeader';
import StatsCard from './StatsCard';
import StatisticsPanel from './StatisticsPanel';
import ActionPanel from './ActionPanel';

// Page transition variants - simplified for better performance
const pageVariants = {
  initial: { 
    opacity: 0, 
    y: 20
  },
  animate: { 
    opacity: 1, 
    y: 0,
    transition: { 
      duration: 0.4,
      ease: "easeInOut",
      staggerChildren: 0.05
    }
  },
  exit: { 
    opacity: 0,
    y: -20,
    transition: { 
      duration: 0.25,
      ease: "easeInOut" 
    }
  }
};

// Shared item variants for staggered animations - simplified
const itemVariants = {
  initial: { opacity: 0, y: 20 },
  animate: { 
    opacity: 1, 
    y: 0,
    transition: { 
      duration: 0.3, 
      ease: "easeInOut" 
    }
  }
};

// Simplified neural connection for better performance
const NeuralConnection = ({ startPos, endPos, delay = 0 }) => (
  <svg className="absolute top-0 left-0 w-full h-full pointer-events-none z-0" style={{ overflow: 'visible' }}>
    <path 
      d={`M${startPos.x},${startPos.y} C${startPos.x + 100},${startPos.y} ${endPos.x - 100},${endPos.y} ${endPos.x},${endPos.y}`}
      stroke="rgba(100, 200, 255, 0.2)"
      strokeWidth="1"
      fill="none"
      strokeDasharray="5,5"
      style={{ opacity: 0.5 }}
    />
    
    <motion.circle
      r="3"
      fill="#80CFFF"
      initial={{ 
        opacity: 0,
        cx: startPos.x,
        cy: startPos.y
      }}
      animate={{ 
        opacity: [0, 0.7, 0],
        cx: [startPos.x, endPos.x],
        cy: [startPos.y, endPos.y]
      }}
      transition={{ 
        duration: 3, 
        delay,
        repeat: Infinity,
        repeatDelay: 5
      }}
    />
  </svg>
);

const DashboardContainer = ({ studyData, tasks }) => {
  const { theme } = useTheme();
  const { addNotification, autoNotify } = useNotification();
  const [completedTasksPercent, setCompletedTasksPercent] = useState(0);
  const [streakDays, setStreakDays] = useState(0);
  const [totalStudyHours, setTotalStudyHours] = useState(0);
  const [userName] = useState('Student');
  const [currentTime, setCurrentTime] = useState(new Date());
  const [greeting, setGreeting] = useState('');
  const [connectionPositions, setConnectionPositions] = useState({});
  
  // Update time every minute
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 60000);
    
    return () => clearInterval(timer);
  }, []);
  
  // Set greeting based on time of day
  useEffect(() => {
    const hour = currentTime.getHours();
    let newGreeting = '';
    
    if (hour >= 5 && hour < 12) {
      newGreeting = 'Good Morning';
    } else if (hour >= 12 && hour < 17) {
      newGreeting = 'Good Afternoon';
    } else if (hour >= 17 && hour < 22) {
      newGreeting = 'Good Evening';
    } else {
      newGreeting = 'Good Night';
    }
    
    setGreeting(newGreeting);
  }, [currentTime]);
  
  // Format time as HH:MM AM/PM
  const formattedTime = currentTime.toLocaleTimeString([], { 
    hour: '2-digit', 
    minute: '2-digit',
    hour12: true 
  });
  
  // Format date as "Tuesday, 5 March"
  const formattedDate = currentTime.toLocaleDateString([], {
    weekday: 'long',
    day: 'numeric',
    month: 'long'
  });
  
  // Calculate statistics from data
  useEffect(() => {
    // Calculate completed tasks percentage
    const completedTasks = tasks.filter(task => task.completed).length;
    const totalTasks = tasks.length;
    const percentage = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;
    
    // Set the percentage directly for better performance
    setCompletedTasksPercent(percentage);
    
    // Calculate total study hours
    const totalHours = studyData.reduce((sum, day) => sum + day.value, 0) / 60;
    setTotalStudyHours(Math.round(totalHours * 10) / 10);
    
    // Set streak days (demo value)
    setStreakDays(5);
    
    // Welcome notification - only show if autoNotify is enabled
    if (autoNotify) {
      setTimeout(() => {
        addNotification(`Welcome back, ${userName}!`, 'info');
      }, 1000);
    }
  }, [tasks, studyData, addNotification, userName, autoNotify]);
  
  // Determine task status based on completion percentage
  const getTaskStatus = () => {
    if (completedTasksPercent >= 80) return 'completed';
    if (completedTasksPercent >= 40) return 'inProgress';
    return 'pending';
  };
  
  // Icons for the stats cards
  const icons = {
    time: (
      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
      </svg>
    ),
    tasks: (
      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
      </svg>
    ),
    streak: (
      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
      </svg>
    )
  };
  
  // Setup neural connections between cards - simplified for better performance
  useEffect(() => {
    const updateConnectionPositions = () => {
      const positions = {};
      
      // Find card elements by their IDs
      const statsPanel = document.getElementById('statistics-panel');
      const actionPanel = document.getElementById('action-panel');
      
      // Calculate center position for stats panel
      if (statsPanel) {
        const rect = statsPanel.getBoundingClientRect();
        positions['stats-panel'] = {
          x: rect.left + rect.width / 2,
          y: rect.top + rect.height / 2
        };
      }
      
      // Calculate center position for action panel
      if (actionPanel) {
        const rect = actionPanel.getBoundingClientRect();
        positions['action-panel'] = {
          x: rect.left + rect.width / 2,
          y: rect.top + rect.height / 2
        };
      }
      
      setConnectionPositions(positions);
    };
    
    // Update positions after initial render
    setTimeout(updateConnectionPositions, 1000);
    
    // Update positions on window resize with debounce for better performance
    let resizeTimer;
    const handleResize = () => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(updateConnectionPositions, 300);
    };
    
    window.addEventListener('resize', handleResize);
    
    return () => {
      clearTimeout(resizeTimer);
      window.removeEventListener('resize', handleResize);
    };
  }, []);
  
  return (
    <motion.div 
      className="max-w-7xl mx-auto px-2 pb-24 relative"
      initial="initial"
      animate="animate"
      exit="exit"
      variants={pageVariants}
    >
      {/* Neural connections between dashboard elements - simplified for better performance */}
      {Object.keys(connectionPositions).length > 0 && (
        <div className="fixed inset-0 pointer-events-none z-0">
          {/* Connect stats panel to action panel */}
          {connectionPositions['stats-panel'] && connectionPositions['action-panel'] && (
            <NeuralConnection 
              key="connection-panels"
              startPos={connectionPositions['stats-panel']}
              endPos={connectionPositions['action-panel']}
              delay={0.5}
            />
          )}
        </div>
      )}
      
      {/* Greeting Header with time display */}
      <GreetingHeader 
        userName={userName}
        greeting={greeting}
        formattedDate={formattedDate}
        formattedTime={formattedTime}
        theme={theme}
      />
      
      {/* Stats Overview with premium cards */}
      <motion.div 
        className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6"
        variants={itemVariants}
      >
        <div className="stats-card" id="stats-card-0">
          <StatsCard 
            title="Total Study Time"
            value={`${totalStudyHours} hours`}
            description={totalStudyHours > 10 
              ? "Great work! You're putting in solid study hours." 
              : "Keep going! Try to increase your study time gradually."}
            icon={icons.time}
            color="blue"
            theme={theme}
          />
        </div>
        
        <div className="stats-card" id="stats-card-1">
          <StatsCard 
            title="Tasks Completed"
            value={`${tasks.filter(task => task.completed).length}/${tasks.length}`}
            description={completedTasksPercent >= 70 
              ? "Excellent progress on your tasks!" 
              : "You have some pending tasks to complete."}
            icon={icons.tasks}
            color="green"
            theme={theme}
          />
        </div>
        
        <div className="stats-card" id="stats-card-2">
          <StatsCard 
            title="Study Streak"
            value={`${streakDays} days`}
            description={streakDays > 3 
              ? "You're on a roll! Keep the momentum going." 
              : "Build a streak by studying every day."}
            icon={icons.streak}
            color="purple"
            theme={theme}
          />
        </div>
      </motion.div>
      
      {/* Statistics Panel */}
      <motion.div
        id="statistics-panel"
        className="glass-panel rounded-xl mb-6 overflow-hidden border border-neural-400/10 shadow-neural"
        variants={itemVariants}
      >
        <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-neural-400/20 to-transparent" />
        
        <div className="p-4">
          <StatisticsPanel 
            studyData={studyData} 
            completionPercentage={completedTasksPercent}
            status={getTaskStatus()}
            theme={theme}
          />
        </div>
      </motion.div>
      
      {/* Action Items Panel */}
      <motion.div
        id="action-panel"
        className="glass-panel rounded-xl overflow-hidden border border-neural-400/10 shadow-neural"
        variants={itemVariants}
      >
        <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-neural-400/20 to-transparent" />
        
        <div className="p-4">
          <ActionPanel 
            tasks={tasks.filter(task => !task.completed).slice(0, 5)}
            theme={theme}
          />
        </div>
      </motion.div>
    </motion.div>
  );
};

export default DashboardContainer; 