import React, { useRef, useEffect } from 'react';
import { motion, useAnimation } from 'framer-motion';

/**
 * Enhanced futuristic greeting header with neural network visual elements
 * Optimized for better performance
 */
const GreetingHeader = ({ userName, greeting, formattedDate, formattedTime, theme }) => {
  const neuralNodesRef = useRef(null);
  const controls = useAnimation();
  
  // Generate random neural node positions - reduced count for better performance
  const neuralNodes = Array.from({ length: 8 }).map(() => ({
    x: Math.random() * 100,
    y: Math.random() * 100,
    size: Math.random() * 4 + 2,
    delay: Math.random() * 2,
    duration: Math.random() * 3 + 2
  }));
  
  // Connect nodes with lines to create neural network effect
  // Reduced connection count for better performance
  const neuralConnections = [];
  for (let i = 0; i < neuralNodes.length; i++) {
    // Connect each node to just 1 other node
    const targetIdx = Math.floor(Math.random() * neuralNodes.length);
    if (targetIdx !== i) {
      neuralConnections.push({
        from: i,
        to: targetIdx,
        opacity: Math.random() * 0.4 + 0.1,
        // Reduce animated connections for better performance
        pulse: Math.random() > 0.8
      });
    }
  }
  
  // Greeting text animation variants
  const textVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.6,
        ease: "easeOut"
      }
    }
  };
  
  // Time and date animation variants
  const timeVariants = {
    hidden: { opacity: 0, scale: 0.9 },
    visible: {
      opacity: 1,
      scale: 1,
      transition: {
        duration: 0.5,
        ease: "easeOut",
        delay: 0.2
      }
    }
  };
  
  // Neural background animation sequence - simplified for better performance
  useEffect(() => {
    controls.start({
      opacity: [0.3, 0.8, 0.3],
      transition: {
        duration: 10,
        repeat: Infinity,
        repeatType: "reverse"
      }
    });
  }, [controls]);
  
  // Convert date to more futuristic format - Year.Month.Day
  const dateObj = new Date();
  const futuristicDate = `${dateObj.getFullYear()}.${String(dateObj.getMonth() + 1).padStart(2, '0')}.${String(dateObj.getDate()).padStart(2, '0')}`;
  
  return (
    <motion.div 
      className="w-full mb-8 relative overflow-hidden rounded-xl"
      initial={{ opacity: 0, y: -20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      {/* Futuristic transparent background with neural network */}
      <div className="absolute inset-0 -z-10 overflow-hidden">
        {/* Gradient background */}
        <div className="absolute inset-0 bg-gray-900/70 backdrop-blur-lg" />
        
        {/* Neural network visualization - simplified for better performance */}
        <motion.div 
          className="absolute inset-0"
          animate={controls}
          ref={neuralNodesRef}
        >
          <svg className="w-full h-full" xmlns="http://www.w3.org/2000/svg">
            {/* Neural connections - reduced count */}
            {neuralConnections.map((connection, idx) => {
              const fromNode = neuralNodes[connection.from];
              const toNode = neuralNodes[connection.to];
              
              return (
                <g key={`connection-${idx}`}>
                  <line
                    x1={`${fromNode.x}%`}
                    y1={`${fromNode.y}%`}
                    x2={`${toNode.x}%`}
                    y2={`${toNode.y}%`}
                    stroke="rgba(100, 200, 255, 0.2)"
                    strokeWidth={0.5}
                    strokeDasharray={connection.pulse ? "5,5" : undefined}
                    style={{ opacity: connection.opacity }}
                  />
                  
                  {/* Only animate a few signals for better performance */}
                  {connection.pulse && (
                    <motion.circle
                      r={2}
                      fill="#80CFFF"
                      initial={{ 
                        cx: `${fromNode.x}%`, 
                        cy: `${fromNode.y}%`,
                        opacity: 0 
                      }}
                      animate={{ 
                        cx: [`${fromNode.x}%`, `${toNode.x}%`],
                        cy: [`${fromNode.y}%`, `${toNode.y}%`],
                        opacity: [0, 0.7, 0]
                      }}
                      transition={{
                        duration: 4,
                        repeat: Infinity,
                        repeatDelay: 4 + Math.random() * 4,
                        ease: "easeInOut"
                      }}
                    />
                  )}
                </g>
              );
            })}
            
            {/* Neural nodes - reduced count and simplified animation */}
            {neuralNodes.map((node, idx) => (
              <motion.circle
                key={`node-${idx}`}
                cx={`${node.x}%`}
                cy={`${node.y}%`}
                r={node.size}
                fill="rgba(100, 200, 255, 0.4)"
                initial={{ opacity: 0.3 }}
                animate={{ 
                  opacity: [0.3, 0.6, 0.3]
                }}
                transition={{
                  duration: node.duration,
                  delay: node.delay,
                  repeat: Infinity,
                  repeatType: "reverse"
                }}
              />
            ))}
          </svg>
        </motion.div>
        
        {/* Horizontal scan line effect - reduced frequency for better performance */}
        <motion.div 
          className="absolute h-px w-full bg-neural-400/30"
          style={{ boxShadow: '0 0 5px rgba(100, 200, 255, 0.3)' }}
          initial={{ top: '-10%', opacity: 0 }}
          animate={{ top: '110%', opacity: [0, 0.2, 0] }}
          transition={{
            duration: 3,
            repeat: Infinity,
            repeatDelay: 8
          }}
        />
      </div>
      
      {/* Content container */}
      <div className="relative py-8 px-6 w-full">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center">
          {/* Left side: Greeting text */}
          <motion.div 
            className="mb-4 md:mb-0"
            variants={textVariants}
            initial="hidden"
            animate="visible"
          >
            <div className="text-sm text-neural-200 mb-1 flex items-center">
              <div className="mr-2 w-2 h-2 rounded-full bg-neural-400 animate-pulse" />
              <span>NEURAL.STUDY.SYSTEM // ACTIVE</span>
            </div>
            
            <h1 className="text-3xl font-bold">
              <span className="neural-text-gradient text-shadow-neural-glow">
                {greeting},
              </span>
              {' '}
              <motion.span 
                className="text-white"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.4, duration: 0.5 }}
              >
                {userName}
              </motion.span>
            </h1>
            
            <motion.p 
              className="text-neural-100/90 text-sm mt-1"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.6, duration: 0.5 }}
            >
              Your neural study network is active and operating at optimal capacity.
            </motion.p>
          </motion.div>
          
          {/* Right side: Date and time */}
          <motion.div 
            className="glass-card p-3 md:p-4 rounded-lg"
            variants={timeVariants}
            initial="hidden"
            animate="visible"
          >
            <div className="flex items-center">
              <div className="mr-4">
                <div className="text-xs text-neural-200/70 mb-1 font-mono">TIMESTAMP</div>
                <div className="text-2xl font-mono text-white text-shadow-neural-glow">
                  {formattedTime}
                </div>
                <div className="text-xs text-neural-200/90 font-mono mt-1 flex items-center">
                  <span className="inline-block w-1.5 h-1.5 rounded-full bg-neural-300 mr-1.5"></span>
                  <span>{futuristicDate}</span>
                </div>
              </div>
              
              <div className="w-px h-14 bg-gradient-to-b from-transparent via-neural-400/50 to-transparent" />
              
              <div className="ml-4">
                <div className="text-xs text-neural-200/70 mb-1 font-mono">CALENDAR</div>
                <div className="text-sm text-white">
                  {formattedDate}
                </div>
                <div className="text-xs text-neural-200/90 mt-1">
                  <div>Session active: 00:{Math.floor(Math.random() * 60)}:{Math.floor(Math.random() * 60)}</div>
                </div>
              </div>
            </div>
          </motion.div>
        </div>
      </div>
      
      {/* Bottom border with glow */}
      <div 
        className="absolute bottom-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-neural-400/30 to-transparent"
        style={{ boxShadow: '0 0 3px rgba(100, 200, 255, 0.3)' }}
      />
    </motion.div>
  );
};

export default GreetingHeader; 